import collections
import datetime
import os
import re

from openpyxl import Workbook
from openpyxl import formatting, styles
from openpyxl.chart import (
    LineChart,
    Reference,
    Series,
)
from openpyxl.styles import Font
from openpyxl.utils import get_column_letter

from taf.ul.bts_kpi_report_generator.Exception import KPIFailSkipMeasurements
from taf.ul.bts_kpi_report_generator.generator.ExcelSetCell import ExcelSetCell
from taf.ul.bts_kpi_report_generator.generator.function_sorted import sorted_names


class SheetCreator(ExcelSetCell):
    def __init__(self, path_dir, number_of_start_interval_to_skip, number_of_end_intervals_to_skip, use_kpi, release_version, warnings, categories,
                 measurements, cells, kpi_exceptions, build, report_name, eg_NB=False):
        """

        :param path_dir:
        :param number_of_start_interval_to_skip:
        :param number_of_end_intervals_to_skip:
        :param use_kpi:
        :param release_version:
        :param warnings:
        :param categories:
        :param measurements:
        :param cells:
        :param kpi_exceptions:
        :param build:
        :param report_name:
        :param eg_NB:
        """
        self.__path_dir = path_dir
        self.__number_of_start_intervals_to_skip = number_of_start_interval_to_skip
        self.__number_of_end_intervals_to_skip = number_of_end_intervals_to_skip
        self.__use_kpi = use_kpi
        self.__release_version = release_version
        self.__warnings = warnings
        self.__categories = categories
        self.__measurements = measurements
        self.__cells = cells
        self.__kpi_exceptions = kpi_exceptions
        self.__build = build
        self.__start_xlsx = str(self.__number_of_start_intervals_to_skip + 2)
        self.__end_xlsx = str(len(self.__measurements) + 1 - self.__number_of_end_intervals_to_skip)
        self.__sheets = {}
        self.__file_xlsx = Workbook()
        self.__report_name = report_name
        self.__name_bts = self.__get_type_bts(eg_NB)

    def generate_report(self):
        """

        :return:
        """
        self.__validate_test_intervals()
        self.__create_details_sheet()
        self.__create_information_sheet()
        self.__create_results_sheet()
        self.__create_sheets_category()
        self.__create_plots()
        self.__file_xlsx.save(os.path.join(self.__path_dir, self.__report_name + '.xlsx'))

    def __get_type_bts(self, eg_NB):
        """

        :param eg_NB:
        :return:
        """
        if eg_NB and '5G' in self.__release_version:
            return 'gNB'
        elif eg_NB and 'LTE' in self.__release_version:
            return 'eNB'
        else:
            return 'BTS'

    def __validate_test_intervals(self):
        """

        :return:
        """
        if int(self.__end_xlsx) < int(self.__start_xlsx):
            raise KPIFailSkipMeasurements

    def __create_details_sheet(self):
        """

        :return:
        """
        self.__sheets['DETAILS'] = self.__file_xlsx.active
        self.__sheets['DETAILS'].title = 'DETAILS'

        start_scenario = self.__measurements[sorted(self.__measurements)[0]].start_time.strftime('%d.%m.%Y %H:%M')
        start_measurement = self.__measurements[sorted(self.__measurements)[
            self.__number_of_start_intervals_to_skip]].start_time.strftime('%d.%m.%Y %H:%M')
        end_measurement = (self.__measurements[sorted(self.__measurements)[-1 - self.__number_of_end_intervals_to_skip]].
                           start_time + datetime.timedelta(minutes=int(self.__measurements[sorted(self.__measurements)[-1]].
                                                                       interval))).strftime('%d.%m.%Y %H:%M')
        end_scenario = (self.__measurements[sorted(self.__measurements)[-1]].start_time + datetime.timedelta(
            minutes=int(self.__measurements[sorted(self.__measurements)[-1]].interval))).strftime('%d.%m.%Y %H:%M')
        test_duration = self.__measurements[sorted(self.__measurements)[-1]].start_time - self.__measurements[sorted(
            self.__measurements)[0]].start_time + datetime.timedelta(minutes=int(self.__measurements[sorted(self.__measurements)[-1]].interval))
        release = self.__release_version

        cell_mapping = {'B2': 'Scenario start:',
                        'C2': start_scenario,
                        'B3': 'Measurements start:',
                        'C3': start_measurement,
                        'B4': 'Measurements end:',
                        'C4': end_measurement,
                        'B5': 'Scenario end:',
                        'C5': end_scenario,
                        'B6': 'Test Duration:',
                        'C6': test_duration,
                        'B7': 'Source release:',
                        'C7': release,
                        'B8': 'Build:',
                        'C8': self.__build,
                        'B9': 'Warnings:'}

        self.__sheets['DETAILS'].column_dimensions['B'].width = 20
        self.__sheets['DETAILS'].column_dimensions['C'].width = 25

        for cell in cell_mapping:
            if 'B' in cell:
                self.fill_cell(self.__sheets['DETAILS'][cell], cell_mapping[cell], bold=True, wrap_text=True)
            else:
                self.fill_cell(self.__sheets['DETAILS'][cell], cell_mapping[cell], horizontal='center', wrap_text=True)

        font_green_bold = Font(color='00008000', bold=True)
        self.__sheets['DETAILS']['C3'].font = font_green_bold
        self.__sheets['DETAILS']['C4'].font = font_green_bold

        if len(self.__warnings) == 0:
            self.fill_cell(self.__sheets['DETAILS'].cell(row=9, column=3), '---', horizontal='center')
        else:
            row = 9
            for warning in sorted(self.__warnings):
                self.fill_cell(self.__sheets['DETAILS'].cell(row=row, column=3), warning, wrap_text=True)
                row = row + 1

    def __create_information_sheet(self):
        """

        :return:
        """
        self.__sheets['INFORMATION'] = self.__file_xlsx.create_sheet('INFORMATION', 1)
        self.__sheets['INFORMATION'].freeze_panes = 'A2'
        column_category = ['KPI_ID', 'NAME', 'CATEGORY', 'DESCRIPTION', 'FORMULA', 'ABBREVIATION', 'LOGICAL_FORMULA', 'UNIT', 'XLSX_FORMULA',
                           'ERRORS']
        for category in column_category:
            self.fill_cell(self.__sheets['INFORMATION'].cell(row=1, column=column_category.index(category) + 1), category, bold=True,
                           horizontal='center')

        columns_dimensions = {'A': 20, 'B': 40, 'C': 20, 'D': 50, 'E': 40, 'F': 30, 'G': 40, 'H': 15, 'I': 40, 'J': 40}
        for column_dimensions in columns_dimensions:
            self.__sheets['INFORMATION'].column_dimensions[column_dimensions].width = columns_dimensions[column_dimensions]

        column_category.remove('KPI_ID')
        row = 2
        for kpi in sorted(self.__use_kpi):
            self.fill_cell(self.__sheets['INFORMATION'].cell(row=row, column=1), kpi, bold=True, horizontal='center')
            column = 2
            for category in column_category:
                if category in self.__use_kpi[kpi]:
                    self.fill_cell(self.__sheets['INFORMATION'].cell(row=row, column=column), str(self.__use_kpi[kpi].get(category, ' ')),
                                   vertical='top', wrap_text=True)
                column += 1
            row += 1

    def __create_results_sheet(self):
        """

        :return:
        """
        self.__sheets['RESULTS'] = self.__file_xlsx.create_sheet('RESULTS', 2)
        self.__sheets['RESULTS'].freeze_panes = 'A2'

        column = 1
        row = 2
        for measurement in sorted(self.__measurements):
            self.fill_cell(self.__sheets['RESULTS'].cell(row=row, column=column), self.__measurements[measurement].
                           start_time.strftime('%d.%m.%Y %H:%M'), horizontal='center')
            self.__sheets['RESULTS'].column_dimensions['A'].width = 30
            row = row + 1

        column = 2
        row = 1
        for kpi in sorted(self.__use_kpi):
            self.__use_kpi[kpi]['COLUMN'] = column
            sorted_cells = sorted(self.__cells, key=sorted_names())
            if kpi in self.__kpi_exceptions:
                object_kpis = sorted_cells + sorted(self.__kpi_exceptions[kpi], key=sorted_names())
                self.__use_kpi[kpi]['OBJECTS'] = object_kpis
            else:
                object_kpis = sorted_cells + [self.__name_bts]
                self.__use_kpi[kpi]['OBJECTS'] = object_kpis

            for object_kpi in object_kpis:
                self.fill_cell(self.__sheets['RESULTS'].cell(row=row, column=column), '{} {}'.format(kpi, object_kpi), bold=True, text_rotation=30)
                row = 2
                for measurement in self.__measurements:
                    self.fill_cell(self.__sheets['RESULTS'].cell(row=row, column=column), self.__measurements[measurement].get_xlsx_formula(
                        self.__use_kpi[kpi]['XLSX_FORMULA'], object_kpi), horizontal='center', number_format='0.00')
                    row = row + 1
                column = column + 1
                row = 1

    def __create_sheets_category(self):
        """

        :return:
        """
        for sheet_category in sorted(self.__categories):
            self.__sheets[sheet_category] = self.__file_xlsx.create_sheet(sheet_category)
            self.__sheets[sheet_category].freeze_panes = 'A2'

            name_columns = collections.OrderedDict()
            name_columns['KPIs'] = 75
            name_columns['Target'] = 10
            name_columns['Value'] = 10
            name_columns['Difference'] = 20
            name_columns['Unit'] = 10
            name_columns['Warnings'] = 20
            name_columns['Information'] = 40

            for column, name_column in enumerate(name_columns, 1):
                self.__sheets[sheet_category].column_dimensions[get_column_letter(column)].width = name_columns[name_column]
                self.fill_cell(self.__sheets[sheet_category].cell(row=1, column=column), name_column, bold=True, horizontal='center',
                               wrap_text=True)

            row = 2
            for kpi in sorted(self.__categories[sheet_category]):
                name = self.__use_kpi[kpi]['NAME']
                target_raw = str(self.__use_kpi[kpi]['TARGET'])
                target = self.__get_target(target_raw)
                compare_formula = self.__get_proper_compare_formula(target_raw)
                information_column = sorted(self.__use_kpi).index(kpi) + 2
                unit = self.__use_kpi[kpi].get('UNIT', ' ')
                column = 0
                for object_kpi in self.__use_kpi[kpi]['OBJECTS']:
                    column_letter = get_column_letter(self.__use_kpi[kpi]['COLUMN'] + column)
                    self.fill_cell(self.__sheets[sheet_category].cell(row=row, column=1), '{} {} {}'.format(kpi, name, object_kpi),
                                   horizontal='center', wrap_text=True)
                    self.fill_cell(self.__sheets[sheet_category].cell(row=row, column=2), target, horizontal='center', wrap_text=True)
                    self.fill_cell(self.__sheets[sheet_category].cell(row=row, column=3), '=IFERROR(AVERAGE(RESULTS!${}${}:${}${}),\"NA\")'.format(
                        column_letter, self.__start_xlsx, column_letter, self.__end_xlsx), horizontal='center', wrap_text=True, number_format='0.00')
                    self.fill_cell(self.__sheets[sheet_category].cell(row=row, column=4), compare_formula.format(
                        row, row, row, row), horizontal='center', wrap_text=True, number_format='0.00')
                    self.fill_cell(self.__sheets[sheet_category].cell(row=row, column=5), unit, horizontal='center', wrap_text=True)
                    self.fill_cell(self.__sheets[sheet_category].cell(row=row, column=6),
                                   '=IF(COUNTIF(RESULTS!${}${}:${}${},\"NA\")>0,\"CHECK PMSTATS!\",\"SEE RESULTS.\")'.
                                   format(column_letter, self.__start_xlsx, column_letter, self.__end_xlsx),
                                   horizontal='center', wrap_text=True, hyperlink='#RESULTS!{}1'.format(column_letter))
                    self.fill_cell(self.__sheets[sheet_category].cell(row=row, column=7), '{} INFO'.format(kpi), horizontal='center',
                                   wrap_text=True, hyperlink='#INFORMATION!A{}'.format(information_column))
                    row = row + 1
                    column = column + 1

                self.fill_cell(self.__sheets[sheet_category].cell(row=row, column=1), '{} {} CELL_AVG'.format(kpi, name), horizontal='center',
                               wrap_text=True)
                self.fill_cell(self.__sheets[sheet_category].cell(row=row, column=3), '=IFERROR(AVERAGE(C{}:C{}),\"NA\")'.
                               format((row - 3), (row - 2)), horizontal='center', wrap_text=True, number_format='0.00')
                row = row + 2

            self.__sheets[sheet_category].conditional_formatting.add('D2:D{}'.format(row), formatting.rule.CellIsRule(
                operator='lessThan', formula=['0'], font=styles.Font(bold=True, color='00FF0000')))
            self.__sheets[sheet_category].conditional_formatting.add('D2:D{}'.format(row), formatting.rule.CellIsRule(
                operator='greaterThan', formula=['0'], font=styles.Font(bold=True, color='00008000')))
            self.__sheets[sheet_category].auto_filter.ref = 'A1:G{}'.format(row)

    def __create_plots(self):
        """

        :return:
        """
        max_row_results = self.__sheets['RESULTS'].max_row
        dates = Reference(self.__sheets['RESULTS'], min_col=1, min_row=2, max_row=max_row_results)

        for category in list(self.__sheets):
            if category in ['DETAILS', 'INFORMATION', 'RESULTS']:
                pass
            else:
                first_plot_row = self.__sheets[category].max_row + 4

                for kpi in sorted(self.__categories[category]):
                    chart = LineChart()
                    chart.title = '{} {}'.format(kpi, self.__use_kpi[kpi]['NAME'])
                    chart.y_axis.title = self.__use_kpi[kpi]['UNIT']
                    chart.x_axis.title = 'Date'
                    for i in range(0, len(self.__use_kpi[kpi]['OBJECTS'])):
                        data = Reference(self.__sheets['RESULTS'], min_col=self.__use_kpi[kpi]['COLUMN'] + i, min_row=2, max_row=max_row_results)
                        chart.append(Series(data, title='{} {}'.format(kpi, self.__use_kpi[kpi]['OBJECTS'][i])))
                    chart.width = 12
                    chart.height = 8
                    chart.set_categories(dates)
                    self.__sheets[category].add_chart(chart, 'A{}'.format(first_plot_row))
                    first_plot_row += 20

    @staticmethod
    def __get_target(target_raw):
        match = re.search(r'^[<>]?(?P<TARGET>\d+)', target_raw)
        if match:
            return match.group('TARGET')
        else:
            return target_raw

    @staticmethod
    def __get_proper_compare_formula(target_raw):
        value_formula_bigger = '=IF(ISERROR(C{}-B{}),\"\",C{}-B{})'
        value_formula_smaller = '=IF(ISERROR(B{}-C{}),\"\",B{}-C{})'
        if target_raw.startswith('<'):
            return value_formula_smaller
        else:
            return value_formula_bigger
